    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/0"],
      "relevance": "'팀장으로서 다른 방법이 안 떠오른 겁니다'라는 진술은 '내 판단이 기준이 되어야 하며 결과로 증명하면 된다'는 규칙의 표현. situations/0에서 인사팀장에게 '실적 한 번 못 내 본 것들이'라고 반발한 자동사고와 같은 구조."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 문제를 '직원이 분기 목표 절반도 못 채운' 상대의 능력 부족으로 귀인하고 있음. situations/1에서 신입 직원의 정당한 지적을 '규정 만든 사람들이 영업을 아느냐'로 상대 자격을 깎아내린 패턴과 일치."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '3년 연속 전사 1등', '8명'을 반복 언급하며 자신의 특별함을 상기시키고 있음. childhood_data에서 '남들 위에 서는 것'만이 보답이라는 경험이 성과 언급을 자기 정당화의 도구로 만들었음."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/situations/0"],
      "relevance": "상담사가 '그 사람에게서 변화가 있었는지' 질문해도 내담자는 자신의 한계(대인관계 기술 부족)를 검토하지 않고 '다른 방법이 안 떠오른 것'으로만 서술. situations/0에서 상담 프로그램 이수를 '가르치려 든다'로 반발한 것과 같은 한계 수용 불가 패턴."
    }
  ]
}

